import AppKit

final class TranscriptBar: NSView, OptionControl {
    static let noWordsShown = 3

    private weak var source: TranscriptTabSource?
    private let stack = NSStackView()
    private let wordsSlot = NSView()
    private let languageSlot = NSView()
    private let statusRow = NSStackView()
    private let statusLabel: InspectorNoteLabel
    private let status: Lines
    private var stopButton: OptionButtonControl!
    private var readButton: OptionButtonControl!
    private let notes = NSStackView()
    private var noteTexts: [String] = []
    private var wordsTitles: [String] = []
    private var languageTitles: [String] = []
    private var wordsPopup: OptionPopupControl?
    private var languagePopup: OptionPopupControl?
    private var retired: [NSView] = []

    init(source: TranscriptTabSource) {
        self.source = source
        let status = Lines()
        self.status = status
        statusLabel = InspectorNoteLabel(wraps: true) {
            status.lines.isEmpty ? nil : status.lines.joined(separator: "\n")
        }
        super.init(frame: .zero)
        stopButton = OptionButtonControl(
            title: "Stop", action: { [weak self] in self?.pressStop() }, enabled: { true }, onEdit: {})
        stopButton.setAccessibilityIdentifier("transcript.stop")
        stopButton.toolTip = "Stop reading on this Mac. A tool call's reading goes on."
        readButton = OptionButtonControl(
            title: "Read", action: { [weak self] in self?.pressRead() }, enabled: { true }, onEdit: {})
        readButton.setAccessibilityIdentifier("transcript.read")
        readButton.toolTip = "Read the files left on this Mac."

        stack.orientation = .vertical
        stack.alignment = .leading
        stack.spacing = InspectorMetrics.rowSpacing
        stack.edgeInsets = NSEdgeInsets(
            top: 8, left: InspectorMetrics.inset, bottom: 6, right: InspectorMetrics.inset)
        stack.translatesAutoresizingMaskIntoConstraints = false
        addSubview(stack)
        NSLayoutConstraint.activate([
            stack.topAnchor.constraint(equalTo: topAnchor),
            stack.leadingAnchor.constraint(equalTo: leadingAnchor),
            stack.trailingAnchor.constraint(equalTo: trailingAnchor),
            stack.bottomAnchor.constraint(equalTo: bottomAnchor),
        ])

        statusRow.orientation = .horizontal
        statusRow.alignment = .top
        statusRow.spacing = 8
        statusRow.distribution = .fill
        statusRow.addArrangedSubview(statusLabel)
        statusRow.addArrangedSubview(stopButton)
        statusRow.addArrangedSubview(readButton)
        // The sentence takes the row; the button keeps its own width.
        statusLabel.setContentHuggingPriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        for button in [stopButton!, readButton!] {
            button.setContentHuggingPriority(.required, for: .horizontal)
            button.setContentCompressionResistancePriority(.required, for: .horizontal)
        }
        notes.orientation = .vertical
        notes.alignment = .leading
        notes.spacing = 4

        let rows: [NSView] = [
            row("Words from", wordsSlot), row("Language", languageSlot), statusRow, notes,
        ]
        for view in rows {
            stack.addArrangedSubview(view)
            view.widthAnchor.constraint(
                equalTo: stack.widthAnchor, constant: -2 * InspectorMetrics.inset
            ).isActive = true
        }
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("TranscriptBar does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    private final class Lines {
        var lines: [String] = []
    }

    private func row(_ title: String, _ slot: NSView) -> NSView {
        let box = NSView()
        let label = InspectorRowLabel(title)
        for view in [label, slot] {
            view.translatesAutoresizingMaskIntoConstraints = false
            box.addSubview(view)
        }
        NSLayoutConstraint.activate([
            label.leadingAnchor.constraint(equalTo: box.leadingAnchor),
            label.widthAnchor.constraint(equalToConstant: InspectorMetrics.labelWidth),
            label.centerYAnchor.constraint(equalTo: box.centerYAnchor),
            slot.leadingAnchor.constraint(equalTo: label.trailingAnchor, constant: 6),
            slot.trailingAnchor.constraint(equalTo: box.trailingAnchor),
            slot.topAnchor.constraint(equalTo: box.topAnchor),
            slot.bottomAnchor.constraint(equalTo: box.bottomAnchor),
            slot.heightAnchor.constraint(equalToConstant: DS.controlHeight),
        ])
        return box
    }

    private func install(_ popup: OptionPopupControl, in slot: NSView) {
        let old = slot.subviews
        retired += old
        for view in old { view.removeFromSuperview() }
        popup.translatesAutoresizingMaskIntoConstraints = false
        popup.setContentHuggingPriority(.defaultLow, for: .horizontal)
        popup.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        slot.addSubview(popup)
        NSLayoutConstraint.activate([
            popup.leadingAnchor.constraint(equalTo: slot.leadingAnchor),
            popup.trailingAnchor.constraint(equalTo: slot.trailingAnchor),
            popup.topAnchor.constraint(equalTo: slot.topAnchor),
            popup.bottomAnchor.constraint(equalTo: slot.bottomAnchor),
        ])
    }

    // MARK: - Refresh

    func refresh() {
        guard let source else { return }
        retired = []
        var moved = refreshPopups(source)
        status.lines = Self.statusText(source.status) ?? []
        statusLabel.refresh()
        let before = [stopButton.isHidden, readButton.isHidden, statusRow.isHidden]
        stopButton.isHidden = !stopShown
        readButton.isHidden = !readShown
        statusRow.isHidden = status.lines.isEmpty && !stopShown && !readShown
        moved = moved || before != [stopButton.isHidden, readButton.isHidden, statusRow.isHidden]
        moved = refreshNotes(source) || moved
        // A view coming or going lands at a zero frame until the next layout
        // pass: lay the window out now, so nothing reads it before then.
        if moved { window?.contentView?.layoutSubtreeIfNeeded() }
    }

    private func refreshPopups(_ source: TranscriptTabSource) -> Bool {
        var rebuilt = false
        let trackChoices: [(title: String, value: UInt32?)] =
            [("All tracks", nil)] + source.tracks.map { ($0.name, Optional($0.id)) }
        let titles = trackChoices.map(\.title)
        if titles != wordsTitles || wordsPopup == nil {
            wordsTitles = titles
            let popup = OptionPopupControl(
                width: InspectorMetrics.popupWidth, choices: trackChoices,
                read: { [weak source] in source?.wordsFrom },
                write: { [weak self] in self?.chooseWordsFrom($0) },
                enabled: { true }, onEdit: {})
            popup.setAccessibilityIdentifier("transcript.words-from")
            wordsPopup = popup
            install(popup, in: wordsSlot)
            rebuilt = true
        } else {
            wordsPopup?.refresh()
        }

        let installed = source.languages ?? []
        // The default's identifier, not its name: "Automatic (English (United
        // States))" runs past the popup's chevron at the inspector's 280 pt.
        let automatic = Transcriber.defaultLanguage(in: installed).map {
            "Automatic (\($0.identifier))"
        } ?? "Automatic"
        let languageChoices: [(title: String, value: String?)] =
            [(automatic, nil)] + installed.map { ($0.displayName, Optional($0.identifier)) }
        let names = languageChoices.map(\.title)
        if names != languageTitles || languagePopup == nil {
            languageTitles = names
            let popup = OptionPopupControl(
                width: InspectorMetrics.popupWidth, choices: languageChoices,
                read: { [weak source] in source?.language },
                write: { [weak self] in self?.chooseLanguage($0) },
                enabled: { [weak source] in !(source?.languages ?? []).isEmpty }, onEdit: {})
            popup.setAccessibilityIdentifier("transcript.language")
            languagePopup = popup
            install(popup, in: languageSlot)
            rebuilt = true
        } else {
            languagePopup?.refresh()
        }
        return rebuilt
    }

    private func refreshNotes(_ source: TranscriptTabSource) -> Bool {
        let rows = source.noWords.map { "\($0.tag) — \($0.reason)" }
        var texts = source.notes + rows.prefix(Self.noWordsShown)
        let rest = Array(rows.dropFirst(Self.noWordsShown))
        if !rest.isEmpty {
            texts.append("…and \(rest.count) more clip\(rest.count == 1 ? "" : "s") with no words.")
        }
        let hidden = notes.isHidden
        notes.isHidden = texts.isEmpty
        guard texts != noteTexts else { return hidden != notes.isHidden }
        noteTexts = texts
        for view in notes.arrangedSubviews { view.removeFromSuperview() }
        for (index, text) in texts.enumerated() {
            let label = InspectorNoteLabel(wraps: true) { text }
            if !rest.isEmpty, index == texts.count - 1 {
                label.toolTip = rest.joined(separator: "\n")
            }
            notes.addArrangedSubview(label)
            label.widthAnchor.constraint(equalTo: notes.widthAnchor).isActive = true
        }
        return true
    }

    static func statusText(_ status: TranscriptTabSource.Status) -> [String]? {
        switch status {
        case .idle, .loading:
            return nil
        case .reading(let name, let fraction, let index, let of):
            return ["Reading “\(name)” on this Mac… \(Int((fraction * 100).rounded(.down))) % (\(index) of \(of))"]
        case .noModel:
            return [
                "This Mac has no speech model installed. Choose File ▸ Generate Captions…, pick "
                    + "a language and press Download."
            ]
        case .failed(let sentences):
            return sentences
        case .stopped(let remaining):
            return ["Stopped. \(remaining) file\(remaining == 1 ? "" : "s") not read on this Mac."]
        }
    }

    // MARK: - The controls' own paths (the dev tool presses these too)

    var stopShown: Bool { source?.canStop ?? false }

    var readShown: Bool {
        if case .stopped = source?.status { return true }
        return false
    }

    func chooseWordsFrom(_ track: UInt32?) {
        source?.setWordsFrom(track)
        refresh()
    }

    func chooseLanguage(_ identifier: String?) {
        source?.setLanguage(identifier)
        refresh()
    }

    func pressStop() {
        guard stopShown else { return }
        source?.stop()
        refresh()
    }

    func pressRead() {
        guard readShown else { return }
        source?.resume()
        refresh()
    }
}
import AppKit

protocol TranscriptHost: AnyObject {
    var transcriptIsPlaying: Bool { get }
    func transcriptSeek(to time: Ticks)
    var transcriptRange: TranscriptCut.Range? { get }
    func transcriptSetRange(_ range: TranscriptCut.Range?)
    @discardableResult func transcriptDelete(_ range: TranscriptCut.Range, name: String) -> Bool
    func transcriptRefuse(_ sentence: String)
}

final class TranscriptPane: InspectorPaneView {
    let transcriptView = TranscriptView(frame: NSRect(x: 0, y: 0, width: 280, height: 400))
    private(set) var source: TranscriptTabSource!
    private(set) var bar: TranscriptBar!
    private let scroll = NSScrollView()
    private weak var lastProject: ReelProject?
    private var shownRebuilds = -1
    private var rangeSet: TranscriptCut.Range?

    private static let table = NSMapTable<InspectorViewController, TranscriptPane>.weakToWeakObjects()

    static func pane(in inspector: InspectorViewController) -> TranscriptPane? {
        table.object(forKey: inspector)
    }

    override var tab: InspectorTab { .transcript }
    override var emptyMessage: String? { nil }
    override var structureSignature: String { "transcript" }

    override init(inspector: InspectorViewController) {
        super.init(inspector: inspector)
        source = TranscriptTabSource(document: inspector.document) { [weak self] in
            self?.sourceChanged()
        }
        bar = TranscriptBar(source: source)
        Self.table.setObject(self, forKey: inspector)

        scroll.translatesAutoresizingMaskIntoConstraints = false
        scroll.hasVerticalScroller = true
        scroll.autohidesScrollers = true
        scroll.drawsBackground = false
        scroll.borderType = .noBorder
        transcriptView.autoresizingMask = [.width]
        scroll.documentView = transcriptView
        addSubview(scroll)
        let collapse = heightAnchor.constraint(equalToConstant: 0)
        collapse.priority = NSLayoutConstraint.Priority(1)
        NSLayoutConstraint.activate([
            scroll.topAnchor.constraint(equalTo: topAnchor),
            scroll.leadingAnchor.constraint(equalTo: leadingAnchor),
            scroll.trailingAnchor.constraint(equalTo: trailingAnchor),
            scroll.bottomAnchor.constraint(equalTo: bottomAnchor),
            collapse,
        ])
        transcriptView.onActivate = { [weak self] index in self?.seek(token: index) }
        transcriptView.onParagraph = { [weak self] index in self?.seek(paragraph: index) }
        transcriptView.onSelect = { [weak self] selection in self?.selectionChanged(selection) }
        transcriptView.onDelete = { [weak self] in self?.deleteWords() }
        transcriptView.onSelectPause = { [weak self] index in self?.pauseSelected(index) }
        NotificationCenter.default.addObserver(
            self, selector: #selector(cacheLanded(_:)), name: .mediaCacheDidChange, object: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("TranscriptPane does not support NSCoder")
    }

    private var host: TranscriptHost? { inspector?.parent as? TranscriptHost }

    override func makeHeader() -> (any OptionControl)? { bar }

    // MARK: - Shown or not

    override func viewDidMoveToSuperview() {
        super.viewDidMoveToSuperview()
        shownChanged()
    }

    override func viewDidMoveToWindow() {
        super.viewDidMoveToWindow()
        shownChanged()
    }

    override func viewDidHide() {
        super.viewDidHide()
        shownChanged()
    }

    override func viewDidUnhide() {
        super.viewDidUnhide()
        shownChanged()
    }

    var isShown: Bool { window != nil && superview != nil && !isHiddenOrHasHiddenAncestor }

    private func shownChanged() {
        let shown = isShown
        if shown { lastProject = inspector?.document?.editedProject }
        source.setShown(shown)
    }

    // MARK: - The inspector's calls

    override func refresh() {
        super.refresh()
        guard isShown, let document = inspector?.document else { return }
        let project = document.editedProject
        guard project !== lastProject || source.isDirty else { return }
        if !document.isLiveEditing { lastProject = project }
        source.update()
    }

    func playheadMoved() {
        guard isShown, let document = inspector?.document else { return }
        transcriptView.setHighlight(
            source.model.highlight(at: document.playhead),
            follow: host?.transcriptIsPlaying ?? false)
    }

    func reveal(_ clips: [ClipSnapshot]) {
        guard let clip = clips.first else { return }
        guard
            let index = source.model.tokens.firstIndex(where: {
                $0.word.clip == clip.id || $0.word.id.nestPath.first == clip.id
            })
        else { return }
        transcriptView.scrollToToken(index)
    }

    // MARK: - The source's changes

    private func sourceChanged() {
        bar.refresh()
        guard source.rebuilds != shownRebuilds, let document = inspector?.document else { return }
        shownRebuilds = source.rebuilds
        let canvas = document.editedProject.snapshot.canvas
        // The pauses, once per rebuild, from the cut's table (TX-34).
        let pauses = TranscriptCut.pauses(source.cutTable(), fps: canvas.fps)
        transcriptView.show(
            source.model, pauses: pauses, fps: canvas.fps, timecodeFrames: canvas.timecodeFrames)
        transcriptView.setHighlight(source.model.highlight(at: document.playhead), follow: false)
        // The selection was re-mapped by identity: while the document's range
        // is still the one it set, the range follows it (TX-31) — a selected
        // pause's re-planned with no seek (TX-34).
        if rangeSet != nil, host?.transcriptRange == rangeSet {
            if let index = transcriptView.pauseSelection, let plan = pausePlan(index) {
                host?.transcriptSetRange(plan.range)
                rangeSet = plan.range
            } else {
                selectionChanged(transcriptView.selection)
            }
        }
    }

    @objc private func cacheLanded(_ note: Notification) {
        let kind = note.userInfo?[MediaImporter.cacheKindKey] as? String
        guard kind == MediaImporter.speechKind || kind == MediaImporter.peaksKind,
            let media = note.userInfo?[MediaImporter.mediaIDKey] as? UInt32
        else { return }
        source.reloadDeviceWords(media: media)
        if kind == MediaImporter.speechKind { source.update() }
    }

    // MARK: - Selecting and deleting words (TX-31, TX-32)

    private func plan(_ selection: ClosedRange<Int>) -> TranscriptCut.Plan? {
        guard let document = inspector?.document else { return nil }
        let container = document.editedProject.snapshot
        return TranscriptCut.plan(
            selection, table: source.cutTable(), container: container,
            total: ShotSplit.clipCount(document.project.snapshot), fps: container.canvas.fps)
    }

    func selectionChanged(_ selection: ClosedRange<Int>?) {
        guard let host else { return }
        guard let selection, let plan = plan(selection) else {
            if rangeSet != nil, host.transcriptRange == rangeSet { host.transcriptSetRange(nil) }
            rangeSet = nil
            return
        }
        transcriptView.adopt(plan.selection)
        let range = plan.range.end > plan.range.start ? plan.range : nil
        host.transcriptSetRange(range)
        rangeSet = range
    }

    func deleteWords() {
        if let index = transcriptView.pauseSelection {
            deletePause(index)
            return
        }
        guard let host, let selection = transcriptView.selection, let plan = plan(selection) else {
            NSSound.beep()
            return
        }
        transcriptView.adopt(plan.selection)
        if let refusal = plan.refusal {
            host.transcriptRefuse(refusal.sentence)
            return
        }
        guard plan.range.end > plan.range.start else {
            NSSound.beep()
            return
        }
        // Cleared first, so the rebuild the cut causes does not re-plan.
        let held = rangeSet
        rangeSet = nil
        if !host.transcriptDelete(plan.range, name: "Delete Words") { rangeSet = held }
    }

    // MARK: - Selecting and deleting a pause (TX-34)

    private func pausePlan(_ index: Int) -> TranscriptCut.PausePlan? {
        guard let document = inspector?.document, transcriptView.pauses.indices.contains(index)
        else { return nil }
        return TranscriptCut.planPause(
            transcriptView.pauses[index], table: source.cutTable(),
            container: document.editedProject.snapshot,
            total: ShotSplit.clipCount(document.project.snapshot))
    }

    func pauseSelected(_ index: Int?) {
        guard let index, let host, let plan = pausePlan(index) else {
            selectionChanged(nil)
            return
        }
        host.transcriptSetRange(plan.range)
        rangeSet = plan.range
        host.transcriptSeek(to: plan.range.start)
    }

    private func deletePause(_ index: Int) {
        guard let host, let plan = pausePlan(index) else {
            NSSound.beep()
            return
        }
        if let refusal = plan.refusal {
            host.transcriptRefuse(refusal.sentence)
            return
        }
        let held = rangeSet
        rangeSet = nil
        if !host.transcriptDelete(plan.range, name: "Delete Pause") { rangeSet = held }
    }

    // MARK: - Seeking

    private func seek(token index: Int) {
        guard source.model.tokens.indices.contains(index) else { return }
        host?.transcriptSeek(to: source.model.tokens[index].word.start)
    }

    private func seek(paragraph index: Int) {
        guard source.model.paragraphs.indices.contains(index) else { return }
        host?.transcriptSeek(to: source.model.paragraphs[index].start)
    }
}

    }

    /// The row is a drag source (§4.3) and nothing about it says so. The
    /// list has no room for a line that does, so the row says it itself.
    static let dragHint =
        "Drag to a timeline track, or onto the canvas. Hold ⌥ to insert, ⇧⌥ to overwrite."

    /// The row's tooltip: the drag hint, and above it, for a copy, where the
    /// copy lives (spec §11 #228-O, Q1 and Q2) — the Media tab has no path
    /// line to say it in.
    static func toolTip(for entry: MediaSnapshot) -> String {
        // A LUT is never dragged (spec §11 GR-8): it is applied as a look.
        if entry.kind == .lut { return "A LUT: apply it to clips as a look." }
        guard let original = entry.original else { return dragHint }
        let folder = (entry.path as NSString).deletingLastPathComponent
        let home =
            folder.hasSuffix("/\(AppSupport.folderName)/Rewrapped")
            ? "Frame Job's Rewrapped folder" : "this project's package"
        return "\(original.path) — copied into \(home).\n" + dragHint
    }

    /// Keeps the tooltip current after a relink or a consolidate; written
    /// only when it changed, so the tooltip manager is not reset each pass.
    func syncToolTip() {
        let wanted = entry.map(Self.toolTip(for:)) ?? Self.dragHint
        if toolTip != wanted { toolTip = wanted }
        NSBezierPath(
            roundedRect: thumb.insetBy(dx: 0.5, dy: 0.5), xRadius: DS.controlRadius,
            yRadius: DS.controlRadius
        ).stroke()

        // The badges moved to the trailing edge: a 52 pt row has no third
        // line to hang them under, and "missing" is the one thing in this
        // list that must never be the part that got cropped.
        var trailing = bounds.maxX - Self.padding
        if missing {
            trailing = drawBadge("missing", endingAt: trailing, color: DS.coral)
        }
        if entry.hasAudio {
            trailing = drawBadge("audio", endingAt: trailing, color: DS.clipAudio)
        }

        let textX = thumb.maxX + Self.gap
        let width = max(trailing - textX, 10)
        // Truncating, not clipping: the meta line is longer than the space a
        // row with badges leaves ("00:00:21:00 · 1080×1920 · 25 fps" against
        // about 150 pt), and `TimelineDraw.label` would cut it mid-glyph — an
        // ellipsis at least says that something was left out.
        TimelineDraw.truncated(
            entry.name, in: CGRect(x: textX, y: 11, width: width, height: 16),
            font: DS.sans(12), color: DS.textStrong)
        TimelineDraw.truncated(
            metaLine(entry), in: CGRect(x: textX, y: 28, width: width, height: 13),
            font: DS.mono(10), color: DS.textMuted)
    }

    private func metaLine(_ entry: MediaSnapshot) -> String {
        var parts: [String] = []
        if entry.duration > 0 {
            parts.append(
                ReelTime.format(entry.duration, fps: entry.fps, frames: true))
        }
        if entry.width > 0, entry.height > 0 {
            parts.append("\(entry.width)×\(entry.height)")
        }
        if entry.hasVideo, entry.fps.double > 0 {
            parts.append("\(entry.fps.displayName) fps")
        }
        if parts.isEmpty { parts.append(entry.kind.displayName) }
        return parts.joined(separator: " · ")
    }

        menu.autoenablesItems = false
        // Two groups: what to do with the file on the timeline, then what to
        // do with the file. The loop shape cannot express a separator, so the
        // groups are two loops with one between them.
        //
        // Reveal in Timeline is DISABLED where the file's only users are
        // inside a nest: a nested clip has no id the TIMELINE's selection can
        // hold (`MediaUsage.swift`), so the item would select nothing and
        // scroll nowhere. That case is exactly the one the pane's old
        // top-level-only usage test could not see. Since road map 2's phase 9
        // there IS a way to reach such a clip — open the nest (⌘↓) and it is
        // at the top level of the view — but that is a different command from
        // this one, which reveals on the timeline.
        for (title, selector) in [
            ("Insert at Playhead", #selector(insertMedia(_:))),
            ("Overwrite at Playhead", #selector(overwriteMedia(_:))),
            ("Reveal in Timeline", #selector(revealInTimeline(_:))),
        ] {
            let item = NSMenuItem(title: title, action: selector, keyEquivalent: "")
            item.target = self
            if selector == #selector(revealInTimeline(_:)) {
                item.isEnabled = pane?.canRevealInTimeline(media) ?? false
            } else if entry?.kind == .lut {
                item.isEnabled = false  // a LUT is not placed (GR-8)
            }
            menu.addItem(item)
        }
        menu.addItem(.separator())
        for (title, selector) in [
            ("Reveal in Finder", #selector(revealMedia(_:))),
            ("Relink…", #selector(relinkMedia(_:))),
            ("Remove", #selector(removeMedia(_:))),
        ] {
            let item = NSMenuItem(title: title, action: selector, keyEquivalent: "")
            item.target = self
            menu.addItem(item)
        }
        return menu
    }

    @objc private func insertMedia(_ sender: Any?) { pane?.place(media, insert: true) }
    @objc private func overwriteMedia(_ sender: Any?) { pane?.place(media, insert: false) }

    @objc private func revealInTimeline(_ sender: Any?) { pane?.revealInTimeline(media) }

    @objc private func revealMedia(_ sender: Any?) { pane?.reveal(media) }
    @objc private func relinkMedia(_ sender: Any?) { pane?.relink(media) }
    @objc private func removeMedia(_ sender: Any?) { pane?.remove(media) }
}

